INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(14259, 'koKR', 'Chodźcie, intruzi...', '', 0),
(15129, 'koKR', '%s zaczyna uzbrajać bombę zbliżeniową!', '', 0),
(15130, 'koKR', 'Kto śmie przerywać-- Co to ma być? Coście zrobili? Wszystko zniszczycie!', '', 0),
(15132, 'koKR', 'Bliżej! Podejdźcie bliżej... i płońcie!', '', 0),
(17670, 'koKR', 'Tak, jak na to zasługujecie!', '', 0),
(17671, 'koKR', 'Twoi przyjaciele wkrótce do ciebie dołączą!', '', 0),
(17672, 'koKR', 'Powodzenia... Przyda się wam.', '', 0),
(17673, 'koKR', 'Nie wolno wam go uwolnić!', '', 0),
(17674, 'koKR', 'Głupie szczeniaki!', '', 0),
(17675, 'koKR', 'Głupcy! On nas wszystkich pozabija!', '', 0),
(17679, 'koKR', 'Mojej pracy nie wolno przerywać!', '', 0),
(17680, 'koKR', 'Może znajdę dla was jakieś zastosowanie...', '', 0),
(17681, 'koKR', 'Gniew... nienawiść... To narzędzia, których mogę użyć.', '', 0),
(17683, 'koKR', 'Zobaczmy, co da się z was zrobić!', '', 0),
(17684, 'koKR', 'Opór jest bezcelowy.', '', 0),
(17685, 'koKR', 'Trzymajcie się... ode mnie... z dala!', '', 0);
